parsed_cmd.cmd:
$sourcePath = 'VAE\VAE_ANALYSIS.ipynb'
$datasetPath = 'VAE\VAE_DATASET_ANALYSIS.ipynb'
$headPath = 'VAE\VAE_HEAD_ANALYSIS.ipynb'
$nb = Get-Content $sourcePath -Raw | ConvertFrom-Json

function Copy-NotebookCell($cell) {
    $json = $cell | ConvertTo-Json -Depth 100
    return $json | ConvertFrom-Json
}

function Clear-NotebookOutputs($cells) {
    foreach ($cell in $cells) {
        if ($cell.cell_type -eq 'code') {
            $cell.outputs = @()
            $cell.execution_count = $null
        }
    }
    return $cells
}

function New-MarkdownCell($text) {
    [pscustomobject]@{
        cell_type = 'markdown'
        id = [guid]::NewGuid().ToString('N').Substring(0,8)
        metadata = [pscustomobject]@{}
        source = ($text -split "(?<=`n)")
    }
}

function Write-Notebook($path, $template, $cells) {
    $out = [ordered]@{
        cells = @(Clear-NotebookOutputs $cells)
        metadata = $template.metadata
        nbformat = $template.nbformat
        nbformat_minor = $template.nbformat_minor
    }
    ($out | ConvertTo-Json -Depth 100) | Set-Content -Path $path -Encoding UTF8
}

$datasetCells = @()
for ($i = 0; $i -le 22; $i++) { $datasetCells += Copy-NotebookCell $nb.cells[$i] }
$datasetCells[0].source = @(
    '# LVS-VAE Dataset Analysis', "`n", "`n",
    'Use this notebook to inspect the compact NumPy dataset and the CSV/parquet-style dataframes generated by `DATASET_GENERATOR.ipynb`.'
)

$headCells = @()
$headCells += New-MarkdownCell "# LVS-VAE Head Performance Analysis`n`nUse this notebook to evaluate LVS-VAE checkpoint performance for the outcome value head, placing-survival head, ensembles, and live PPO progress gates."
$headCells += New-MarkdownCell "### Setup and Dataset Load"
foreach ($idx in @(2, 6, 8, 10)) { $headCells += Copy-NotebookCell $nb.cells[$idx] }
for ($i = 23; $i -lt $nb.cells.Count; $i++) { $headCells += Copy-NotebookCell $nb.cells[$i] }

Write-Notebook $datasetPath $nb $datasetCells
Write-Notebook $headPath $nb $headCells

Write-Output "Wrote $datasetPath with $($datasetCells.Count) cells"
Write-Output "Wrote $headPath with $($headCells.Count) cells"

