    train_mode: str,
) -> list[torch.nn.Parameter]:
    """Freeze/unfreeze model parts for the selected training stage."""
    set_module_trainable(model, False)

    if train_mode == "joint":
        set_module_trainable(model, True)
    elif train_mode == "reconstruction":
        for module in (
            model.encoder,
            model.mu_layer,
            model.logvar_layer,
            model.decoder,
            model.reconstruction_head,
        ):
            set_module_trainable(module, True)
    elif train_mode == "prediction_heads":
        set_module_trainable(model.value_head, True)
        set_module_trainable(model.placing_survival_head, True)
    elif train_mode == "placing_survival_head":
        set_module_trainable(model.placing_survival_head, True)
    else:
        raise ValueError(
            f"TRAIN_MODE must be one of {sorted(VALID_TRAIN_MODES)}, got {train_mode!r}"
        )

    return [parameter for parameter in model.parameters() if parameter.requires_grad]


def resolve_effective_loss_weights(
    train_mode: str,
    beta: float,
    value_weight: float,
    placing_survival_weight: float,
) -> tuple[float, float, float]:
    """Disable losses that should not train the selected stage."""
    if train_mode == "reconstruction":
        return beta, 0.0, 0.0
    if train_mode == "prediction_heads":
        return 0.0, value_weight, placing_survival_weight
    if train_mode == "placing_survival_head":
        return 0.0, 0.0, placing_survival_weight
    return beta, value_weight, placing_survival_weight


def validate_config(config: TrainConfig) -> None:
    """Fail early when top-of-file training configs are invalid."""
    if config.train_mode not in VALID_TRAIN_MODES:
        raise ValueError(
            f"TRAIN_MODE must be one of {sorted(VALID_TRAIN_MODES)}, "
            f"got {config.train_mode!r}"
        )
    if config.best_model_metric not in VALID_LOSS_METRICS:
        raise ValueError(
            f"BEST_MODEL_METRIC must be one of {sorted(VALID_LOSS_METRICS)}, "
            f"got {config.best_model_metric!r}"
        )
    if (
        config.train_mode in {"prediction_heads", "placing_survival_head"}
        and not config.init_checkpoint_path
    ):
        raise ValueError(
            f"INIT_CHECKPOINT_PATH is required for TRAIN_MODE={config.train_mode!r} "
            "so heads train on a pretrained, frozen latent space."
        )
    if config.epochs <= 0:
        raise ValueError(f"EPOCHS must be positive, got {config.epochs}")
    if config.batch_size <= 0:
        raise ValueError(f"BATCH_SIZE must be positive, got {config.batch_size}")
    if config.learning_rate <= 0:
        raise ValueError(f"LEARNING_RATE must be positive, got {config.learning_rate}")
    if config.placing_survival_weight < 0:
        raise ValueError(
            "PLACING_SURVIVAL_WEIGHT cannot be negative, "
            f"got {config.placing_survival_weight}"

